import React from 'react';
import * as THREE from 'three';
import {EscenaProps, Pieza, Etiqueta, Ojos, aparecer, rebote, flotar, mover, momento} from '../lib3d';

export const Escena0: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [rojo, crema, azul, mostaza] = paleta.acentos;
  const carton = '#A87B52';
  const cartonOsc = '#8C6440';
  const verdeCable = '#3E6B45';
  const focos = ['#B5544A', '#D2AE4E', '#4A76AC'];

  // Golpes sincronizados con la voz
  const tPunta = momento(palabras, fps, 'punta', 48);
  const tArma = momento(palabras, fps, 'arma', 92);
  const tNudo = momento(palabras, fps, 'nudo', 112);
  const tAgitan = momento(palabras, fps, 'agitan', 135);
  const tCaja = momento(palabras, fps, 'caja', Math.round(duracion * 0.85));

  // Temblor del cable y sacudida fuerte de la caja
  const agita = aparecer(frame, tAgitan, 6);
  const amp = 0.006 + 0.03 * agita;
  const jit = (i: number, k: number) => Math.sin(frame * (0.9 + 0.5 * agita) + i * 1.7 + k * 2.3) * amp;
  const golpeCaja = rebote(frame, fps, tCaja);
  const sacudeZ = Math.sin(frame * 1.1) * 0.035 * agita;
  const sacudeX = Math.sin(frame * 0.8 + 1) * 0.03 * agita;

  // Avance de la punta: ya asoma en el fotograma 0, se cuela por el lazo al decir "punta"
  const p = frame < tPunta ? mover(frame, [0, tPunta], [0.3, 0.42]) : mover(frame, [tPunta, tPunta + 30], [0.42, 1]);
  // El lazo se cierra cuando "arma" el nudo
  const r = mover(frame, [tArma, tArma + 14], [0.17, 0.11]);
  const C = new THREE.Vector3(0.15, 0.86, 0.05);

  // Cable principal: del suelo, sobre el borde, enrollado en la caja, lazo de pie y vuelta a la punta
  const main: THREE.Vector3[] = [
    new THREE.Vector3(1.0, 0.03, 0.78),
    new THREE.Vector3(0.78, 0.12, 0.62),
    new THREE.Vector3(0.6, 0.58, 0.45),
    new THREE.Vector3(0.38, 0.56, 0.22),
  ];
  for (let i = 0; i <= 14; i++) {
    const th = (i / 14) * Math.PI * 3;
    main.push(new THREE.Vector3(0.4 * Math.cos(th), 0.5 + 0.06 * (i / 14), 0.27 * Math.sin(th)));
  }
  main.push(new THREE.Vector3(0.12, 0.62, C.z));
  for (let i = 0; i <= 10; i++) {
    const th = (i / 10) * Math.PI * 2;
    main.push(new THREE.Vector3(C.x - 0.03 + 0.06 * (i / 10), C.y - r * Math.cos(th), C.z + r * Math.sin(th)));
  }
  main.push(new THREE.Vector3(-0.05, 0.62, -0.1), new THREE.Vector3(-0.3, 0.52, 0.0));
  main.forEach((v, i) => {
    if (i > 1) v.add(new THREE.Vector3(jit(i, 0), jit(i, 1), jit(i, 2)));
  });

  // Recorrido de la punta (la "serpiente" que se cuela por el lazo)
  const cola = new THREE.CatmullRomCurve3([
    new THREE.Vector3(-0.3, 0.52, 0.0),
    new THREE.Vector3(-0.42, 0.68, 0.18),
    new THREE.Vector3(-0.36, 0.95, 0.24),
    new THREE.Vector3(-0.14, 1.04, 0.1),
    new THREE.Vector3(0.03, 0.9, C.z),
    new THREE.Vector3(C.x, C.y, C.z),
    new THREE.Vector3(0.32, 0.84, 0.06),
    new THREE.Vector3(0.48, 0.73, 0.15),
    new THREE.Vector3(0.56, 0.63, 0.26),
  ]);
  const pts = [...main];
  for (let i = 1; i <= 12; i++) {
    const v = cola.getPoint((i / 12) * p);
    pts.push(v.add(new THREE.Vector3(jit(i + 40, 0), jit(i + 40, 1), jit(i + 40, 2))));
  }
  const curva = new THREE.CatmullRomCurve3(pts);
  const tubo = new THREE.TubeGeometry(curva, 260, 0.018, 8, false);
  const tuboBorde = new THREE.TubeGeometry(curva, 260, 0.026, 8, false);

  const punta = pts[pts.length - 1];
  const tang = curva.getTangentAt(1).normalize();
  const qPunta = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), tang);
  const PT: [number, number, number] = [punta.x, punta.y, punta.z];

  // Focos repartidos por el cable
  const bulbos: React.ReactNode[] = [];
  for (let i = 0; i < 13; i++) {
    const u = 0.08 + i * 0.066;
    const v = curva.getPointAt(Math.min(0.92, u));
    bulbos.push(
      <Pieza key={i} forma="capsula" medidas={[0.028, 0.04]} color={focos[i % 3]} posicion={[v.x, v.y + 0.035, v.z]} rotacion={[0.3 * Math.sin(i), 0, 0.4 * Math.cos(i * 2)]} />,
    );
  }

  // Círculo rojo que marca la punta (visible desde el fotograma 0)
  const aroEsc = (0.7 + 0.3 * rebote(frame, fps, 0)) * (1 + 0.08 * Math.sin(frame / 4)) * (1 + 0.25 * rebote(frame, fps, tPunta));
  const aroNudo = aparecer(frame, tNudo, 8);

  return (
    <group>
      {/* Fondo: árbol y estante con cartelito oscuro de oferta */}
      <group position={[-1.35, 0, -1.7]}>
        <Pieza forma="cilindro" medidas={[0.06, 0.07, 0.25]} color={cartonOsc} posicion={[0, 0.12, 0]} />
        <Pieza forma="cono" medidas={[0.5, 0.6]} color="#4F6B4A" posicion={[0, 0.5, 0]} />
        <Pieza forma="cono" medidas={[0.4, 0.5]} color="#567552" posicion={[0, 0.85, 0]} />
        <Pieza forma="cono" medidas={[0.28, 0.42]} color="#5C7C57" posicion={[0, 1.15, 0]} />
        <Pieza forma="esfera" medidas={[0.05]} color={mostaza} posicion={[0, 1.4, 0]} />
        <Pieza forma="esfera" medidas={[0.04]} color={focos[0]} posicion={[0.2, 0.6, 0.35]} />
        <Pieza forma="esfera" medidas={[0.04]} color={focos[2]} posicion={[-0.15, 0.95, 0.28]} />
      </group>
      <group position={[1.35, 0, -1.8]}>
        <Pieza forma="caja" medidas={[0.9, 0.05, 0.3]} color={crema} posicion={[0, 1.0, 0]} />
        <Pieza forma="caja" medidas={[0.05, 1.0, 0.3]} color="#C2BBAF" posicion={[-0.42, 0.5, 0]} />
        <Pieza forma="caja" medidas={[0.05, 1.0, 0.3]} color="#C2BBAF" posicion={[0.42, 0.5, 0]} />
        <Pieza forma="caja" medidas={[0.5, 0.3, 0.03]} color="#2A2A2E" posicion={[0, 1.2, 0]} brillo="#5A3A1A" intensidadBrillo={0.3} />
        <Pieza forma="caja" medidas={[0.4, 0.04, 0.035]} color={mostaza} posicion={[0, 1.25, 0.01]} />
        <Pieza forma="caja" medidas={[0.25, 0.25, 0.25]} color={carton} posicion={[0.1, 0.15, 0]} />
      </group>

      {/* Medio: la caja de cartón entreabierta que se sacude */}
      <group position={[0, 0.03 * golpeCaja, 0]} rotation={[sacudeX, flotar(frame, 0.05, 120), sacudeZ]}>
        <Pieza forma="caja" medidas={[1.3, 0.03, 0.9]} color={cartonOsc} posicion={[0, 0.015, 0]} />
        <Pieza forma="caja" medidas={[1.3, 0.55, 0.03]} color={carton} posicion={[0, 0.275, -0.435]} />
        <Pieza forma="caja" medidas={[1.3, 0.55, 0.03]} color={carton} posicion={[0, 0.275, 0.435]} />
        <Pieza forma="caja" medidas={[0.03, 0.55, 0.9]} color={carton} posicion={[-0.635, 0.275, 0]} />
        <Pieza forma="caja" medidas={[0.03, 0.55, 0.9]} color={carton} posicion={[0.635, 0.275, 0]} />
        {/* solapas abiertas */}
        <Pieza forma="caja" medidas={[1.3, 0.025, 0.42]} color={carton} posicion={[0, 0.62, 0.62]} rotacion={[0.45 + 0.15 * golpeCaja, 0, 0]} />
        <Pieza forma="caja" medidas={[1.3, 0.025, 0.42]} color={carton} posicion={[0, 0.7, -0.6]} rotacion={[-0.7, 0, 0]} />
        <Pieza forma="caja" medidas={[0.4, 0.025, 0.86]} color={cartonOsc} posicion={[-0.82, 0.62, 0]} rotacion={[0, 0, -0.55]} />
        <Pieza forma="caja" medidas={[0.4, 0.025, 0.86]} color={cartonOsc} posicion={[0.84, 0.6, 0]} rotacion={[0, 0, 0.5 - 0.1 * golpeCaja]} />
        {/* cinta amarilla vieja en el frente */}
        <Pieza forma="caja" medidas={[0.12, 0.3, 0.01]} color={mostaza} posicion={[-0.3, 0.42, 0.455]} />
        <Pieza forma="caja" medidas={[0.3, 0.12, 0.01]} color="#7A5636" posicion={[0.35, 0.3, 0.455]} />
      </group>

      {/* Protagonista: la tira de luces */}
      <group rotation={[sacudeX * 0.6, 0, sacudeZ * 0.6]}>
        <mesh geometry={tubo} castShadow>
          <meshToonMaterial color={verdeCable} />
        </mesh>
        <mesh geometry={tuboBorde}>
          <meshBasicMaterial color="#1B1B1F" side={THREE.BackSide} />
        </mesh>
        {bulbos}

        {/* Enchufe blanco con ojos curiosos */}
        <group position={PT} quaternion={qPunta}>
          <Pieza forma="caja" medidas={[0.075, 0.11, 0.05]} color="#F2EEE6" posicion={[0, 0.045, 0]} />
          <Pieza forma="cilindro" medidas={[0.025, 0.03, 0.03]} color="#E3DED4" posicion={[0, -0.02, 0]} />
          <Pieza forma="caja" medidas={[0.012, 0.05, 0.004]} color="#B8B2A6" posicion={[-0.02, 0.12, 0]} metal={0.8} />
          <Pieza forma="caja" medidas={[0.012, 0.05, 0.004]} color="#B8B2A6" posicion={[0.02, 0.12, 0]} metal={0.8} />
          <Ojos posicion={[0, 0.06, 0.028]} tam={0.022} separacion={0.04} frame={frame} mirar={[mover(frame, [tPunta, tPunta + 10], [-0.6, 0.6]), 0.4]} />
        </group>

        {/* Círculo rojo que marca la punta */}
        <mesh position={PT} rotation={[-0.55, 0.62, 0]} scale={aroEsc}>
          <torusGeometry args={[0.13, 0.011, 8, 48]} />
          <meshBasicMaterial color={rojo} toneMapped={false} />
        </mesh>

        {/* Al formarse el nudo, el lazo se resalta en azul */}
        {aroNudo > 0.001 ? (
          <mesh position={[C.x, C.y, C.z]} rotation={[0, Math.PI / 2, 0]} scale={aroNudo * (1 + 0.1 * Math.sin(frame / 3))}>
            <torusGeometry args={[r + 0.06, 0.01, 8, 48]} />
            <meshBasicMaterial color={azul} toneMapped={false} />
          </mesh>
        ) : null}
      </group>

      {/* Textos */}
      <Etiqueta texto="la punta ataca" punto={PT} desplazamiento={[0.22, 0.55, 0.05]} escala={aparecer(frame, tPunta, 8)} />
      <Etiqueta texto="nudo" punto={[C.x - 0.05, C.y + r, C.z]} desplazamiento={[-0.6, 0.45, 0]} escala={aparecer(frame, tNudo, 8)} />

      {/* Delante: cartón gris para enrollar y rollo de cinta */}
      <Pieza forma="caja" medidas={[0.42, 0.02, 0.28]} color="#9E9890" posicion={[-0.85, 0.01, 0.85]} rotacion={[0, 0.4, 0]} />
      <group position={[-0.35, 0.035, 1.05]} rotation={[Math.PI / 2, 0, 0]}>
        <Pieza forma="toro" medidas={[0.07, 0.03]} color={mostaza} />
      </group>
    </group>
  );
};

escenas.Escena3:
import React from 'react';
import * as THREE from 'three';
import {EscenaProps, Pieza, Etiqueta, Flecha, Ojos, Aro, Brillo, Linea, aparecer, rebote, flotar, mover, momento} from '../lib3d';

type P3 = [number, number, number];

const mezcla = (a: string, b: string, k: number) =>
  '#' + new THREE.Color(a).lerp(new THREE.Color(b), Math.max(0, Math.min(1, k))).getHexString();

export const Escena3: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [rojo, crema, azul, mostaza] = paleta.acentos;
  const verdeCable = '#4F7A4A';
  const gris = '#A8A398';
  const madera = '#B58A5E';
  const maderaOscura = '#8E6843';
  const carton = '#A57C52';

  // Golpes con la voz
  const tY = momento(palabras, fps, 'y', 1);
  const tRaro = momento(palabras, fps, 'raro', 14);
  const tNudo = momento(palabras, fps, 'nudo', 43);
  const tSiempre = momento(palabras, fps, 'siempre', 58);
  const tExt = momento(palabras, fps, 'extremo', 90);
  const tCuerda = momento(palabras, fps, 'cuerda', Math.round(duracion * 0.82));

  // Sacudida inicial de la caja (primer golpe)
  const sac = Math.max(0, 1 - (frame - tY) / 28) * (frame >= tY ? 1 : 0);
  const cajaGiro = Math.sin(frame * 0.9) * 0.035 * sac;
  const cajaX = Math.sin(frame * 1.3) * 0.02 * sac;

  // Atenuado del resto de la cuerda en "extremo"
  const dim = aparecer(frame, tExt, 12);
  const colorCable = mezcla(verdeCable, gris, dim * 0.85);
  const coloresFoco = ['#B9573F', '#D4A03C', '#5E7FA8'].map((c) => mezcla(c, gris, dim * 0.8));

  // Punta: avanza como serpiente hacia las vueltas
  const e0: P3 = [0.5, 0.6, 0.28];
  const e1: P3 = [0.18, 0.6, 0.18];
  const e2: P3 = [-0.1, 0.585, 0.03];
  const k1 = mover(frame, [tNudo, tExt], [0, 1]);
  const k2 = mover(frame, [tExt, tCuerda + 18], [0, 1]);
  const lerp3 = (a: P3, b: P3, k: number): P3 => [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k];
  const velocidad = frame > tSiempre ? 2.6 : 4.5;
  const serp = Math.sin(frame / velocidad) * 0.035;
  const base = lerp3(lerp3(e0, e1, k1), e2, k2);
  const E: P3 = [base[0] + serp * 0.4, base[1], base[2] + serp];

  // Cuerpo enrollado
  const N = 46;
  const cuerpo: P3[] = [];
  for (let i = 0; i <= N; i++) {
    const t = i / N;
    const a = t * Math.PI * 2 * 2.3 + 0.4;
    const r = 0.24 - t * 0.03;
    const cx = -0.3 + 0.38 * t;
    const vib = Math.sin(frame * 0.8 + i) * 0.008 * sac;
    cuerpo.push([cx + r * Math.cos(a) + vib, 0.585 + 0.018 * Math.sin(a * 0.5) + t * 0.02, r * 0.8 * Math.sin(a) + vib]);
  }
  const fin = cuerpo[N];
  // Tramo de la punta (bezier con ondulación)
  const ctrl: P3 = [(fin[0] + E[0]) / 2 + 0.12, 0.6, (fin[2] + E[2]) / 2 + 0.18];
  const M = 16;
  const punta: P3[] = [];
  for (let i = 1; i <= M; i++) {
    const t = i / M;
    const u = 1 - t;
    const ond = Math.sin(frame / velocidad - t * 5) * 0.03 * t;
    punta.push([
      u * u * fin[0] + 2 * u * t * ctrl[0] + t * t * E[0] + ond * 0.5,
      u * u * fin[1] + 2 * u * t * ctrl[1] + t * t * E[1],
      u * u * fin[2] + 2 * u * t * ctrl[2] + t * t * E[2] + ond,
    ]);
  }
  const ruta = [...cuerpo, ...punta];
  const prev = ruta[ruta.length - 3];
  const rumbo = Math.atan2(-(E[2] - prev[2]), E[0] - prev[0]);

  // Resalte de la punta
  const pulso = 1 + Math.sin(frame / 4) * 0.08;
  const anillo = aparecer(frame, tExt, 10);
  const salto = rebote(frame, fps, tRaro);
  const saltoExt = rebote(frame, fps, tExt);
  const nudoRing = aparecer(frame, tNudo, 10) * (1 - dim * 0.6);

  return (
    <group>
      {/* Fondo: árbol de Navidad y estante con caja de cartón */}
      <group position={[-1.55, 0, -1.7]}>
        <Pieza forma="cilindro" medidas={[0.07, 0.08, 0.3]} color={maderaOscura} posicion={[0, 0.15, 0]} />
        <Pieza forma="cono" medidas={[0.55, 0.7]} color="#4E6B4A" posicion={[0, 0.6, 0]} />
        <Pieza forma="cono" medidas={[0.42, 0.6]} color="#557352" posicion={[0, 1.0, 0]} />
        <Pieza forma="cono" medidas={[0.28, 0.5]} color="#5B7A57" posicion={[0, 1.38, 0]} />
        <Pieza forma="esfera" medidas={[0.06]} color={mostaza} posicion={[0, 1.66, 0]} />
        {[[0.3, 0.55, 0.32], [-0.25, 0.85, 0.3], [0.15, 1.15, 0.25], [-0.2, 0.5, 0.4]].map((p, i) => (
          <Pieza key={i} forma="esfera" medidas={[0.045]} color={[rojo, mostaza, crema, rojo][i]} posicion={p as P3} />
        ))}
      </group>
      <group position={[1.45, 0, -1.7]} rotation={[0, -0.4, 0]}>
        <Pieza forma="caja" medidas={[0.9, 0.04, 0.35]} color={madera} posicion={[0, 0.6, 0]} />
        <Pieza forma="caja" medidas={[0.9, 0.04, 0.35]} color={madera} posicion={[0, 1.15, 0]} />
        <Pieza forma="caja" medidas={[0.04, 1.2, 0.35]} color={maderaOscura} posicion={[-0.45, 0.6, 0]} />
        <Pieza forma="caja" medidas={[0.04, 1.2, 0.35]} color={maderaOscura} posicion={[0.45, 0.6, 0]} />
        <Pieza forma="caja" medidas={[0.42, 0.3, 0.28]} color={carton} posicion={[-0.15, 0.77, 0]} />
        <Pieza forma="caja" medidas={[0.42, 0.01, 0.14]} color={carton} posicion={[-0.15, 0.97, 0.18]} rotacion={[-1.0, 0, 0]} />
        <Pieza forma="cilindro" medidas={[0.07, 0.07, 0.2]} color={crema} posicion={[0.25, 1.27, 0]} />
      </group>

      {/* Mesa */}
      <Pieza forma="caja" medidas={[1.7, 0.06, 1.3]} color={madera} posicion={[0, 0.5, 0]} />
      {[[-0.75, -0.55], [0.75, -0.55], [-0.75, 0.55], [0.75, 0.55]].map(([x, z], i) => (
        <Pieza key={i} forma="caja" medidas={[0.07, 0.47, 0.07]} color={maderaOscura} posicion={[x, 0.235, z]} />
      ))}

      {/* Caja de acrílico con la cuerda */}
      <group position={[cajaX, 0, 0]} rotation={[0, 0, cajaGiro]}>
        <Pieza forma="caja" medidas={[1.2, 0.03, 0.8]} color={crema} posicion={[0, 0.545, 0]} />
        {[
          {p: [0, 0.77, -0.4], m: [1.2, 0.42, 0.01]},
          {p: [0, 0.77, 0.4], m: [1.2, 0.42, 0.01]},
          {p: [-0.6, 0.77, 0], m: [0.01, 0.42, 0.8]},
          {p: [0.6, 0.77, 0], m: [0.01, 0.42, 0.8]},
        ].map((w, i) => (
          <Pieza key={i} forma="caja" medidas={w.m} color="#DDE6EA" posicion={w.p as P3} opacidad={0.18} contorno={false} />
        ))}
        {[-0.6, 0.6].flatMap((x) =>
          [-0.4, 0.4].map((z) => (
            <Linea key={`v${x}${z}`} desde={[x, 0.56, z]} hasta={[x, 0.98, z]} grosor={0.005} color="#1B1B1F" />
          )),
        )}
        {[0.56, 0.98].flatMap((y) => [
          <Linea key={`a${y}`} desde={[-0.6, y, -0.4]} hasta={[0.6, y, -0.4]} grosor={0.005} color="#1B1B1F" />,
          <Linea key={`b${y}`} desde={[-0.6, y, 0.4]} hasta={[0.6, y, 0.4]} grosor={0.005} color="#1B1B1F" />,
          <Linea key={`c${y}`} desde={[-0.6, y, -0.4]} hasta={[-0.6, y, 0.4]} grosor={0.005} color="#1B1B1F" />,
          <Linea key={`d${y}`} desde={[0.6, y, -0.4]} hasta={[0.6, y, 0.4]} grosor={0.005} color="#1B1B1F" />,
        ])}

        {/* Cable */}
        {ruta.slice(1).map((p, i) => {
          const enPunta = i >= N;
          return (
            <Linea key={i} desde={ruta[i]} hasta={p} grosor={0.018} color={enPunta ? verdeCable : colorCable} />
          );
        })}
        {/* Focos */}
        {cuerpo.filter((_, i) => i % 4 === 2).map((p, i) => (
          <Pieza key={i} forma="capsula" medidas={[0.022, 0.04]} color={coloresFoco[i % 3]} posicion={[p[0], p[1] + 0.035, p[2]]} rotacion={[0.3 * Math.sin(i), 0, 0.3 * Math.cos(i)]} />
        ))}
        {punta.filter((_, i) => i % 6 === 3).map((p, i) => (
          <Pieza key={`pf${i}`} forma="capsula" medidas={[0.022, 0.04]} color={['#B9573F', '#D4A03C', '#5E7FA8'][(i + 1) % 3]} posicion={[p[0], p[1] + 0.035, p[2]]} />
        ))}
        {/* Cruce del nudo */}
        <Aro posicion={[-0.12, 0.57, 0.02]} radio={0.1} color={mostaza} progreso={nudoRing} grosor={0.012} />

        {/* La punta: enchufe blanco con ojos */}
        <group position={[E[0], E[1] + 0.02 + 0.04 * salto + 0.03 * saltoExt, E[2]]} rotation={[0, rumbo, 0]} scale={1 + 0.15 * saltoExt}>
          <Pieza forma="caja" medidas={[0.13, 0.06, 0.08]} color="#F2EFE8" />
          <Pieza forma="caja" medidas={[0.05, 0.012, 0.012]} color="#B8B3A8" metal={0.6} posicion={[0.09, 0, 0.022]} />
          <Pieza forma="caja" medidas={[0.05, 0.012, 0.012]} color="#B8B3A8" metal={0.6} posicion={[0.09, 0, -0.022]} />
          <Ojos posicion={[0.02, 0.035, 0]} rotacion={[-Math.PI / 2, 0, -Math.PI / 2]} tam={0.026} separacion={0.045}
            mirar={[mover(frame, [tRaro, tRaro + 8], [0, 0.6]) * (1 - k1), 0.6]} frame={frame} />
        </group>
        <Aro posicion={[E[0], 0.565, E[2]]} radio={0.15 * pulso * anillo} color={azul} progreso={anillo} grosor={0.016} />
        {anillo > 0.01 ? <Brillo posicion={[E[0], E[1] + 0.09, E[2]]} color={azul} radio={0.02 * anillo} luz={0.6 * anillo} /> : null}
        <Flecha desde={[0.48, 0.7, 0.32]} hasta={[0.02, 0.66, 0.1]} color={azul} grosor={0.014} progreso={mover(frame, [tCuerda, tCuerda + 12], [0, 1])} />
      </group>

      {/* Etiquetas */}
      <Etiqueta texto="nudo" punto={[-0.14, 0.62, 0.02]} desplazamiento={[-0.45, 0.48, 0]} escala={aparecer(frame, tNudo, 8)} />
      <Etiqueta texto="la punta" punto={[E[0], E[1] + 0.05, E[2]]} desplazamiento={[0.42, 0.5, 0.15]} color={azul} escala={aparecer(frame, tExt, 8)} />

      {/* Delante: cartón para enrollar y cinta adhesiva */}
      <Pieza forma="caja" medidas={[0.36, 0.012, 0.22]} color="#9C978E" posicion={[-0.58, 0.54, 0.52]} rotacion={[0, 0.25, 0]} />
      <Pieza forma="toro" medidas={[0.065, 0.032]} color={mostaza} posicion={[0.64, 0.565 + flotar(frame, 0.004, 50), 0.5]} rotacion={[Math.PI / 2, 0, 0]} />
    </group>
  );
};

escenas.Escena2:
import React from 'react';
import * as THREE from 'three';
import {EscenaProps, Pieza, Etiqueta, Ojos, Aro, Mat, aparecer, flotar, mover, momento} from '../lib3d';

// Nudos tóricos reales: (2,3)=trébol, (2,5), (2,7) y (2,11), que tiene exactamente 11 cruces.
const geos = new Map<string, THREE.TorusKnotGeometry>();
const geoNudo = (p: number, q: number, r: number, t: number) => {
  const k = [p, q, r, t].join(',');
  let g = geos.get(k);
  if (!g) {
    g = new THREE.TorusKnotGeometry(r, t, 260, 12, p, q);
    geos.set(k, g);
  }
  return g;
};

const Nudo: React.FC<{p: number; q: number; posicion: [number, number, number]; escala: number; giro: number; color: string; radio?: number}> = ({
  p,
  q,
  posicion,
  escala,
  giro,
  color,
  radio = 0.13,
}) => (
  <group position={posicion} rotation={[0.15, giro, 0]} scale={escala}>
    <mesh geometry={geoNudo(p, q, radio, 0.024)} castShadow receiveShadow>
      <Mat color={color} />
    </mesh>
    <mesh geometry={geoNudo(p, q, radio, 0.031)}>
      <meshBasicMaterial color="#1B1B1F" side={THREE.BackSide} />
    </mesh>
  </group>
);

export const Escena2: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [rojo, crema, azul, mostaza] = paleta.acentos;
  const madera = '#B08458';
  const maderaOscura = '#8A6440';
  const cuerda = '#CDB48C';
  const cuerdaOscura = '#9E865F';
  const carton = '#B08A5E';
  const pino = '#5E7A55';

  const tSal = momento(palabras, fps, 'salieron', 1);
  const tNudos = momento(palabras, fps, 'nudos', 11);
  const tSimples = momento(palabras, fps, 'simples', 20);
  const tOtros = momento(palabras, fps, 'otros', 37);
  const tComplejos = momento(palabras, fps, 'complejos', 42);
  const tOnce = momento(palabras, fps, 'once', 75);
  const tCruces = momento(palabras, fps, 'cruces', 91);
  const tTodo = momento(palabras, fps, 'todo', 120);
  const tCuerda = momento(palabras, fps, 'cuerda', 147);
  const tTrenzada = momento(palabras, fps, 'trenzada', 158);
  const tCaja = momento(palabras, fps, 'caja', 190);
  const tGiraba = momento(palabras, fps, 'giraba', Math.min(duracion - 20, 204));

  const pulso = (t: number, d = 10) => aparecer(frame, t, 4) * (1 - aparecer(frame, t + 4, d));
  const vis = (a: number, b?: number) => aparecer(frame, a, 8) * (b === undefined ? 1 : 1 - aparecer(frame, b, 8));

  const yTabla = 0.72;
  const nudos = [
    {p: 2, q: 3, x: -0.6, esc: 0.85, t: tNudos, nivel: 0.27},
    {p: 2, q: 5, x: -0.2, esc: 0.95, t: tOtros, nivel: 0.45},
    {p: 2, q: 7, x: 0.2, esc: 1.05, t: tComplejos, nivel: 0.64},
    {p: 2, q: 11, x: 0.6, esc: 1.15, t: tOnce, nivel: 1},
  ];

  // Caja de acrílico del experimento: gira, y más rápido al decir "caja".
  const giroCaja = frame * 0.02 + Math.max(0, frame - tCaja) * 0.14;
  const arco = aparecer(frame, tGiraba, 10);
  const trenza = mover(frame, [tCuerda, tCuerda + 14], [0, 1]);
  const ojosMirar: [number, number] = [mover(frame, [tCruces, tCruces + 8], [0, -0.7]), mover(frame, [tCruces, tCruces + 8], [0, 0.4])];

  return (
    <group>
      {/* Fondo: árbol de Navidad */}
      <group position={[-1.05, 0, -0.85]}>
        <Pieza forma="cilindro" medidas={[0.05, 0.06, 0.25]} color={maderaOscura} posicion={[0, 0.12, 0]} />
        <Pieza forma="cono" medidas={[0.42, 0.6]} color={pino} posicion={[0, 0.5, 0]} />
        <Pieza forma="cono" medidas={[0.34, 0.5]} color={pino} posicion={[0, 0.85, 0]} />
        <Pieza forma="cono" medidas={[0.24, 0.42]} color={pino} posicion={[0, 1.15, 0]} />
        <Pieza forma="esfera" medidas={[0.05]} color={mostaza} posicion={[0, 1.4, 0]} />
        {[[0.2, 0.45, 0.25, rojo], [-0.18, 0.7, 0.22, azul], [0.12, 0.95, 0.2, mostaza], [-0.08, 1.12, 0.15, rojo]].map(([x, y, z, c], i) => (
          <Pieza key={i} forma="esfera" medidas={[0.035]} color={c as string} posicion={[x as number, y as number, z as number]} contorno={false} />
        ))}
      </group>

      {/* Fondo: caja de acrílico girando con una cuerda dentro */}
      <group position={[0.95, 0, -0.85]}>
        <Pieza forma="caja" medidas={[0.3, 0.3, 0.3]} color={crema} posicion={[0, 0.15, 0]} />
        <group position={[0, 0.55, 0]} rotation={[0, 0, giroCaja]}>
          <Pieza forma="caja" medidas={[0.4, 0.4, 0.4]} color="#DDE6EA" opacidad={0.3} />
          <Nudo p={2} q={3} posicion={[0, 0, 0]} escala={0.7} giro={0.4} color={cuerda} />
        </group>
        <Pieza forma="cilindro" medidas={[0.03, 0.03, 0.5]} color="#8C8C8C" metal={0.6} posicion={[0, 0.55, -0.05]} rotacion={[Math.PI / 2, 0, 0]} />
        {arco > 0.001 ? (
          <group position={[0, 0.55, 0.24]} rotation={[0, 0, -frame * 0.05]} scale={arco}>
            <Pieza forma="toro" medidas={[0.32, 0.015, Math.PI * 1.4]} color={azul} contorno={false} />
            <Pieza forma="cono" medidas={[0.04, 0.09]} color={azul} posicion={[0.32, 0, 0]} rotacion={[0, 0, 0]} contorno={false} />
          </group>
        ) : null}
      </group>

      {/* Fondo: caja de cartón con luces */}
      <group position={[1.05, 0, 0.1]} rotation={[0, -0.4, 0]}>
        <Pieza forma="caja" medidas={[0.34, 0.24, 0.3]} color={carton} posicion={[0, 0.12, 0]} />
        <Pieza forma="caja" medidas={[0.34, 0.015, 0.2]} color={carton} posicion={[0, 0.3, -0.2]} rotacion={[-1.1, 0, 0]} />
        {[rojo, mostaza, azul].map((c, i) => (
          <Pieza key={i} forma="capsula" medidas={[0.022, 0.04]} color={c} posicion={[-0.09 + i * 0.09, 0.27, 0.02]} rotacion={[0.3, 0, 0.4 - i * 0.4]} brillo={c} intensidadBrillo={0.2} />
        ))}
      </group>

      {/* Medio: estante de madera con los nudos en fila */}
      <group>
        <Pieza forma="caja" medidas={[1.7, 0.05, 0.42]} color={madera} posicion={[0, yTabla, 0]} />
        <Pieza forma="caja" medidas={[1.7, 0.04, 0.4]} color={madera} posicion={[0, 0.35, 0]} />
        <Pieza forma="caja" medidas={[1.7, 0.04, 0.4]} color={maderaOscura} posicion={[0, 0.03, 0]} />
        {[-1, 1].map((l) => (
          <Pieza key={l} forma="caja" medidas={[0.05, 0.72, 0.42]} color={maderaOscura} posicion={[0.85 * l, 0.36, 0]} />
        ))}
        <Pieza forma="caja" medidas={[1.7, 0.7, 0.02]} color={crema} posicion={[0, 0.36, -0.2]} />

        {nudos.map((n, i) => {
          const s = n.esc * (1 + 0.22 * pulso(n.t) + 0.12 * pulso(tSal + i * 3) + 0.15 * pulso(tTodo + i * 3));
          const lleno = mover(frame, [n.t, n.t + 12], [0, n.nivel]);
          return (
            <group key={i}>
              <Pieza forma="cilindro" medidas={[0.12, 0.13, 0.04]} color={maderaOscura} posicion={[n.x, yTabla + 0.045, 0]} />
              <Nudo p={n.p} q={n.q} posicion={[n.x, yTabla + 0.07 + 0.17 * n.esc, 0]} escala={s} giro={flotar(frame + i * 20, 0.35, 90)} color={i === 3 ? cuerda : cuerdaOscura} />
              {/* medidor de enredo en el canto del estante: sube de izquierda a derecha */}
              <Pieza forma="caja" medidas={[0.32, 0.03, 0.01]} color="#6E6860" posicion={[n.x, yTabla, 0.215]} contorno={false} />
              <Pieza forma="caja" medidas={[0.32, 0.032, 0.012]} color={i === 3 ? azul : crema} posicion={[n.x - 0.16 + 0.16 * lleno, yTabla, 0.222]} escala={[lleno, 1, 1]} contorno={false} />
            </group>
          );
        })}
        <Aro posicion={[0.6, yTabla + 0.03, 0]} radio={0.2} color={azul} progreso={aparecer(frame, tOnce, 12)} />
        <Ojos posicion={[0.6, yTabla + 0.045, 0.13]} tam={0.028} separacion={0.07} mirar={ojosMirar} frame={frame} />

        {/* Cuerda trenzada recta en el estante de abajo */}
        {trenza > 0.001 ? (
          <group position={[-0.65, 0.4, 0.05]} scale={[trenza, 1, 1]}>
            <Pieza forma="cilindro" medidas={[0.025, 0.025, 1.3]} color={cuerda} posicion={[0.65, 0, 0]} rotacion={[0, 0, Math.PI / 2]} />
            {Array.from({length: 16}).map((_, i) => (
              <mesh key={i} position={[0.05 + i * 0.08, 0, 0.012]} rotation={[0, 0, 0.7]}>
                <boxGeometry args={[0.012, 0.055, 0.03]} />
                <Mat color={cuerdaOscura} />
              </mesh>
            ))}
          </group>
        ) : null}
      </group>

      {/* Etiquetas (máximo dos a la vez) */}
      <Etiqueta texto="simples" punto={[-0.6, yTabla + 0.3, 0]} desplazamiento={[-0.15, 0.55, 0.1]} escala={vis(tSimples, tOnce - 3)} />
      <Etiqueta texto="complejos" punto={[0.2, yTabla + 0.35, 0]} desplazamiento={[-0.1, 0.55, 0.1]} escala={vis(tComplejos, tOnce)} />
      <Etiqueta texto="11 cruces" punto={[0.6, yTabla + 0.4, 0]} desplazamiento={[-0.05, 0.5, 0.15]} color="#FFFFFF" alto={0.2} escala={vis(tOnce)} />
      <Etiqueta texto="trenzada" punto={[-0.45, 0.42, 0.08]} desplazamiento={[-0.55, 0.2, 0.35]} escala={vis(tTrenzada)} />

      {/* Delante: tramo de luces en el suelo */}
      <group position={[-0.55, 0, 0.85]} rotation={[0, 0.3, 0]}>
        <Pieza forma="cilindro" medidas={[0.012, 0.012, 0.7]} color={pino} posicion={[0, 0.015, 0]} rotacion={[0, 0, Math.PI / 2]} />
        {[rojo, mostaza, azul, rojo].map((c, i) => (
          <Pieza key={i} forma="capsula" medidas={[0.025, 0.045]} color={c} posicion={[-0.27 + i * 0.18, 0.05, 0]} rotacion={[0, 0, flotar(frame + i * 15, 0.15, 70)]} brillo={c} intensidadBrillo={0.15} />
        ))}
        <Pieza forma="caja" medidas={[0.07, 0.05, 0.05]} color="#EFECE6" posicion={[0.39, 0.03, 0]} />
      </group>
    </group>
  );
};

escenas.Escena1:
import React from 'react';
import * as THREE from 'three';
import {EscenaProps, Pieza, Etiqueta, Cartel, Ojos, Brillo, Aro, aparecer, rebote, flotar, mover, momento} from '../lib3d';

const S = 0.9; // lado de la caja de acrílico
const H = S / 2;
const CY = 0.95; // altura del centro de giro

export const Escena1: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [terracota, crema, azul, mostaza] = paleta.acentos;
  const cuerdaColor = '#C9A877';
  const acrilico = '#CFD8DA';
  const metal = '#8E8C88';
  const carton = '#A77B4F';
  const verde = '#4E7A52';

  // Golpes con la voz
  const tParte = momento(palabras, fps, 'parte', 6);
  const tCuerda = momento(palabras, fps, 'cuerda', 37);
  const tAgitada = momento(palabras, fps, 'agitada', 49);
  const tCaja = momento(palabras, fps, 'caja', 69);
  const tAnuda = momento(palabras, fps, 'anuda', 83);
  const tNudos = momento(palabras, fps, 'nudos', 129);
  const tEmpiezan = momento(palabras, fps, 'empiezan', Math.round(duracion * 0.84));

  // Giro de la caja: ya gira desde el fotograma 0, acelera al "agitada"
  const acel = aparecer(frame, tAgitada, 15);
  const ang = 0.35 + frame * 0.04 + mover(frame, [tAgitada, tAgitada + 60], [0, 1.6]) - acel * 0;
  const golpeCaja = rebote(frame, fps, tCaja);
  const golpeInicio = rebote(frame, fps, 0);

  // Cuerda dentro de la caja (coordenadas de la caja)
  const amp = 0.55 + 0.45 * acel;
  const nudo = aparecer(frame, tAnuda - 4, 16);
  const pulso = 1 + 0.35 * rebote(frame, fps, tCuerda) * (1 - aparecer(frame, tCuerda + 12, 10));
  const salto = 0.08 * Math.abs(Math.sin(frame * 0.21)) * amp;
  const puntos: THREE.Vector3[] = [];
  const N = 18;
  for (let i = 0; i < N; i++) {
    const t = i / (N - 1);
    let x = -0.34 + 0.68 * t;
    let y = -0.2 + salto + amp * 0.17 * Math.sin(t * 6 + frame * 0.17);
    let z = amp * 0.2 * Math.cos(t * 5 + frame * 0.13);
    if (t > 0.5 && t < 0.92) {
      const a = ((t - 0.5) / 0.42) * Math.PI * 2;
      x += nudo * -0.15 * Math.sin(a);
      y += nudo * 0.13 * (1 - Math.cos(a));
      z += nudo * 0.09 * Math.sin(a * 0.5);
    }
    puntos.push(new THREE.Vector3(x, y, z));
  }
  const curva = new THREE.CatmullRomCurve3(puntos);
  const radio = 0.04 * pulso;
  const inicio = puntos[0];
  const punta = puntos[N - 1];

  // De coordenadas de la caja al mundo
  const aMundo = (p: THREE.Vector3): [number, number, number] => [
    p.x * Math.cos(ang) - p.y * Math.sin(ang),
    CY + p.x * Math.sin(ang) + p.y * Math.cos(ang),
    p.z,
  ];
  const puntaMundo = aMundo(punta);
  const lazo = aMundo(new THREE.Vector3(puntos[13].x, puntos[13].y, puntos[13].z));

  // La punta se resalta al "empiezan"
  const resaltePunta = aparecer(frame, tEmpiezan, 8);
  const colorPunta = resaltePunta > 0.5 ? azul : cuerdaColor;

  // Textos
  const escParte = aparecer(frame, tParte, 8) * (1 - aparecer(frame, tCuerda + 10, 8));
  const escAnuda = aparecer(frame, tAnuda + 2, 8) * (1 - aparecer(frame, tNudos - 14, 8));
  const escPregunta = rebote(frame, fps, tNudos - 8);

  // Aristas del acrílico
  const aristas: React.ReactNode[] = [];
  const signos: [number, number][] = [[-1, -1], [-1, 1], [1, -1], [1, 1]];
  signos.forEach(([a, b], i) => {
    aristas.push(<Pieza key={`x${i}`} forma="caja" medidas={[S, 0.03, 0.03]} color={acrilico} posicion={[0, a * H, b * H]} />);
    aristas.push(<Pieza key={`y${i}`} forma="caja" medidas={[0.03, S, 0.03]} color={acrilico} posicion={[a * H, 0, b * H]} />);
    aristas.push(<Pieza key={`z${i}`} forma="caja" medidas={[0.03, 0.03, S]} color={acrilico} posicion={[a * H, b * H, 0]} />);
  });
  const tornillos = signos.map(([a, b], i) => (
    <Pieza key={`t${i}`} forma="cilindro" medidas={[0.018, 0.018, 0.02]} color={metal} posicion={[a * (H - 0.05), b * (H - 0.05), H + 0.01]} rotacion={[Math.PI / 2, 0, 0]} />
  ));

  // Bombillas de la tira enrollada (capa delantera)
  const focos = [terracota, mostaza, azul, terracota, mostaza, azul, terracota];

  return (
    <group>
      {/* ---------- Fondo: sala de diciembre ---------- */}
      <group position={[-1.45, 0, -1.7]}>
        <Pieza forma="cilindro" medidas={[0.07, 0.07, 0.3]} color="#6E4B32" posicion={[0, 0.15, 0]} />
        <Pieza forma="cono" medidas={[0.55, 0.7]} color="#4F6B4E" posicion={[0, 0.6, 0]} />
        <Pieza forma="cono" medidas={[0.44, 0.6]} color="#56755A" posicion={[0, 1.0, 0]} />
        <Pieza forma="cono" medidas={[0.3, 0.5]} color="#5D7D60" posicion={[0, 1.37, 0]} />
        <Pieza forma="esfera" medidas={[0.05]} color={mostaza} posicion={[0, 1.66, 0]} />
        <Pieza forma="esfera" medidas={[0.045]} color={terracota} posicion={[0.22, 0.85, 0.3]} />
        <Pieza forma="esfera" medidas={[0.045]} color={azul} posicion={[-0.18, 1.15, 0.25]} />
      </group>
      <group position={[1.45, 0, -1.7]}>
        <Pieza forma="caja" medidas={[0.8, 0.04, 0.3]} color="#9C7A58" posicion={[0, 1.0, 0]} />
        <Pieza forma="caja" medidas={[0.8, 0.04, 0.3]} color="#9C7A58" posicion={[0, 0.5, 0]} />
        <Pieza forma="caja" medidas={[0.36, 0.3, 0.26]} color={carton} posicion={[-0.15, 0.67, 0]} />
        <Pieza forma="caja" medidas={[0.42, 0.28, 0.03]} color="#2A2A2E" posicion={[0.1, 1.3, -0.1]} />
        <Pieza forma="caja" medidas={[0.3, 0.05, 0.035]} color={mostaza} posicion={[0.1, 1.3, -0.08]} contorno={false} brillo={mostaza} />
      </group>

      {/* ---------- Medio: el experimento ---------- */}
      {/* soporte y motor detrás de la caja */}
      <Pieza forma="caja" medidas={[1.1, 0.06, 0.55]} color="#7A746C" posicion={[0, 0.03, -0.62]} />
      <Pieza forma="caja" medidas={[0.16, 0.92, 0.16]} color={metal} posicion={[0, 0.5, -0.72]} />
      <Pieza forma="cilindro" medidas={[0.13, 0.13, 0.18]} color={terracota} posicion={[0, CY, -0.6]} rotacion={[Math.PI / 2, 0, 0]} />
      <Pieza forma="cilindro" medidas={[0.025, 0.025, 0.14]} color={metal} posicion={[0, CY, -0.48]} rotacion={[Math.PI / 2, 0, 0]} />
      <Pieza forma="cilindro" medidas={[0.035, 0.035, 0.05]} color="#2A2A2E" posicion={[0.2, 0.2, -0.38]} rotacion={[Math.PI / 2, 0, 0]} />
      <Aro posicion={[0, 0, 0]} radio={0.62} color={azul} progreso={aparecer(frame, tCaja, 14) * (1 - aparecer(frame, tAnuda, 10))} />

      <group position={[0, CY, 0]} rotation={[0, 0, ang]} scale={1 + 0.04 * golpeCaja + 0.03 * golpeInicio}>
        {/* caja de acrílico */}
        <Pieza forma="caja" medidas={[S, S, S]} color="#E8F0F1" opacidad={0.16} contorno={false} />
        {aristas}
        {tornillos}
        {/* cuerda gruesa */}
        <mesh castShadow>
          <tubeGeometry args={[curva, 110, radio, 10, false]} />
          <meshToonMaterial color={cuerdaColor} />
        </mesh>
        <mesh>
          <tubeGeometry args={[curva, 110, radio * 1.25, 10, false]} />
          <meshBasicMaterial color="#1B1B1F" side={THREE.BackSide} />
        </mesh>
        <Pieza forma="esfera" medidas={[radio * 1.05]} color={cuerdaColor} posicion={[inicio.x, inicio.y, inicio.z]} />
        <Pieza forma="esfera" medidas={[radio * 1.15]} color={colorPunta} posicion={[punta.x, punta.y, punta.z]} escala={1 + 0.4 * rebote(frame, fps, tEmpiezan)} />
      </group>

      {/* la punta curiosa */}
      {resaltePunta > 0 ? (
        <group>
          <Brillo posicion={[puntaMundo[0], puntaMundo[1], puntaMundo[2] + 0.02]} color={azul} radio={0.018} />
          <Ojos
            posicion={[puntaMundo[0], puntaMundo[1] + 0.07, puntaMundo[2] + 0.06]}
            tam={0.035 * resaltePunta}
            separacion={0.075}
            mirar={[flotar(frame, 0.8, 30), 0.4]}
            frame={frame}
          />
        </group>
      ) : null}

      {/* ---------- Textos ---------- */}
      <Etiqueta texto="parte 2" punto={[-0.38, 1.3, 0.46]} desplazamiento={[-0.32, 0.34, 0]} escala={escParte} />
      <Etiqueta
        texto="se anuda"
        punto={lazo}
        desplazamiento={[0.78 - lazo[0], 1.55 - lazo[1], 0.3 - lazo[2]]}
        escala={escAnuda}
        color={crema}
      />
      <Cartel
        texto="?"
        posicion={[0, 1.76 + flotar(frame, 0.02, 40), 0.3]}
        alto={0.24}
        fondo="transparent"
        colorTexto={azul}
        borde="#1B1B1F"
        escala={escPregunta}
      />

      {/* ---------- Delante: tira de luces enrollada y caja de cartón ---------- */}
      <group position={[-0.8, 0.04, 1.0]} rotation={[0, 0.3, 0]}>
        <Pieza forma="toro" medidas={[0.17, 0.018]} color={verde} rotacion={[Math.PI / 2, 0, 0]} />
        <Pieza forma="toro" medidas={[0.13, 0.018]} color={verde} posicion={[0, 0.03, 0]} rotacion={[Math.PI / 2, 0, 0]} />
        {focos.map((c, i) => {
          const a = (i / focos.length) * Math.PI * 2;
          return <Pieza key={i} forma="capsula" medidas={[0.018, 0.03]} color={c} posicion={[Math.cos(a) * 0.17, 0.04, Math.sin(a) * 0.17]} rotacion={[0, 0, 0.5]} />;
        })}
        <Pieza forma="caja" medidas={[0.07, 0.04, 0.05]} color="#EDEAE3" posicion={[0.24, 0.02, 0.04]} />
      </group>
      <group position={[0.85, 0, 1.05]} rotation={[0, -0.4, 0]}>
        <Pieza forma="caja" medidas={[0.38, 0.26, 0.3]} color={carton} posicion={[0, 0.13, 0]} />
        <Pieza forma="caja" medidas={[0.38, 0.01, 0.14]} color="#B88A5C" posicion={[0, 0.3, -0.2]} rotacion={[-0.9, 0, 0]} />
        <Pieza forma="caja" medidas={[0.4, 0.035, 0.012]} color={mostaza} posicion={[0, 0.2, 0.152]} contorno={false} />
      </group>
    </group>
  );
};

escenas.Escena5:
import React from 'react';
import {EscenaProps, Pieza, Etiqueta, Linea, Ojos, Aro, aparecer, rebote, flotar, mover, momento} from '../lib3d';

type V3 = [number, number, number];

const VERDE_CABLE = '#4E7A4A';
const FOCOS = ['#B5574A', '#D4A03C', '#4F78A8'];

// Caja de acrílico transparente: paredes translúcidas + aristas finas.
const CajaAcrilico: React.FC<{tam: V3; color?: string}> = ({tam, color = '#5A5A60'}) => {
  const [w, h, d] = tam;
  const g = 0.014;
  const aristas: {p: V3; m: V3}[] = [];
  for (const sy of [-1, 1])
    for (const sz of [-1, 1]) aristas.push({p: [0, (sy * h) / 2, (sz * d) / 2], m: [w + g, g, g]});
  for (const sx of [-1, 1])
    for (const sz of [-1, 1]) aristas.push({p: [(sx * w) / 2, 0, (sz * d) / 2], m: [g, h, g]});
  for (const sx of [-1, 1])
    for (const sy of [-1, 1]) aristas.push({p: [(sx * w) / 2, (sy * h) / 2, 0], m: [g, g, d]});
  return (
    <group>
      <Pieza forma="caja" medidas={[w, h, d]} color="#DDE6EA" opacidad={0.16} contorno={false} />
      <Pieza forma="caja" medidas={[w, 0.012, d]} color="#C9D3D7" posicion={[0, -h / 2 + 0.006, 0]} contorno={false} opacidad={0.5} />
      {aristas.map((a, i) => (
        <Pieza key={i} forma="caja" medidas={a.m} color={color} posicion={a.p} contorno={false} />
      ))}
    </group>
  );
};

const Palomita: React.FC<{posicion: V3; escala: number}> = ({posicion, escala}) => {
  if (escala <= 0.001) return null;
  const verde = '#5E9B5A';
  return (
    <group position={posicion} scale={escala}>
      <Pieza forma="caja" medidas={[0.16, 0.05, 0.05]} color={verde} posicion={[-0.08, -0.02, 0]} rotacion={[0, 0, -0.8]} />
      <Pieza forma="caja" medidas={[0.3, 0.05, 0.05]} color={verde} posicion={[0.07, 0.06, 0]} rotacion={[0, 0, 0.95]} />
    </group>
  );
};

export const Escena5: React.FC<EscenaProps> = ({frame, fps, duracion, palabras, paleta}) => {
  const [rojo, crema, azul, mostaza] = paleta.acentos;

  const tOjo = momento(palabras, fps, 'ojo', 3);
  const tCaja = momento(palabras, fps, 'caja', 45);
  const tPeq = momento(palabras, fps, 'pequeña', 58);
  const tCuerda = momento(palabras, fps, 'cuerda', 88);
  const tRigida = momento(palabras, fps, 'rígida', Math.round(duracion * 0.64));
  const tAnuda = momento(palabras, fps, 'anudaba', 125);
  const tMenos = momento(palabras, fps, 'menos', 135);

  // Mesa
  const mesaY = 0.58;
  const madera = '#A88462';
  const maderaOsc = '#7E5F43';

  // Caja grande: se agita sin parar, con un sobresalto en "ojo" y en "caja"
  const golpeOjo = rebote(frame, fps, tOjo);
  const sacudida = 1 + 1.6 * aparecer(frame, tCaja, 4) * (1 - aparecer(frame, tCaja + 10, 10));
  const giroGrande = Math.sin(frame / 4.5) * 0.045 * sacudida;
  const altoG = 0.7;
  const grandeY = mesaY + 0.03 + altoG / 2 + Math.abs(Math.sin(frame / 4.5)) * 0.015 + (1 - golpeOjo) * 0.04;

  // Caja chica: rebota al decir "pequeña"
  const altoC = 0.4;
  const saltoC = rebote(frame, fps, tPeq);
  const chicaY = mesaY + 0.03 + altoC / 2 + Math.sin(Math.min(1, Math.max(0, (frame - tPeq) / 12)) * Math.PI) * 0.08;
  const giroChica = Math.sin(frame / 4.5 + 1) * 0.02;

  // Nudos dentro de la caja grande
  const nudos: {p: V3; r: V3}[] = [
    {p: [-0.17, -0.18, 0.02], r: [0.4, 0.2, 0]},
    {p: [0.1, -0.12, 0.06], r: [1.2, 0.6, 0.3]},
    {p: [-0.06, 0.06, -0.06], r: [0.2, 1.3, 0.5]},
    {p: [0.18, 0.08, 0.02], r: [0.9, -0.4, 1.1]},
    {p: [-0.22, 0.04, 0.1], r: [-0.6, 0.8, 0.2]},
    {p: [0.0, -0.22, -0.12], r: [1.5, 0.1, -0.4]},
    {p: [0.06, 0.18, 0.08], r: [0.3, -1.0, 0.7]},
  ];
  const latidoNudos = 1 + 0.08 * Math.sin(Math.min(1, Math.max(0, (frame - tAnuda) / 14)) * Math.PI);

  // Cuerda rígida: se resalta en "rígida"
  const resalteRigida = aparecer(frame, tRigida, 6);
  const pulsoCuerda = 1 + 0.12 * Math.sin(Math.min(1, Math.max(0, (frame - tCuerda) / 10)) * Math.PI);

  // Textos (máx. 2 a la vez)
  const eCajaChica = aparecer(frame, tPeq + 4, 8) * (1 - aparecer(frame, tRigida, 6));
  const eRigida = aparecer(frame, tRigida + 2, 8);
  const eMenos = aparecer(frame, tMenos, 8);
  const palomita = rebote(frame, fps, tMenos);

  // Ojos de la punta: miran a la caja chica cuando se habla de ella
  const mirarX = mover(frame, [tPeq, tPeq + 10], [-0.2, 0.9]);
  const mirarY = mover(frame, [tMenos, tMenos + 8], [0.2, -0.4]);

  return (
    <group>
      {/* ---------- FONDO ---------- */}
      {/* Árbol de Navidad */}
      <group position={[-1.6, 0, -2.4]}>
        <Pieza forma="cilindro" medidas={[0.07, 0.08, 0.3]} color={maderaOsc} posicion={[0, 0.15, 0]} />
        <Pieza forma="cono" medidas={[0.6, 0.8]} color="#5D7356" posicion={[0, 0.65, 0]} />
        <Pieza forma="cono" medidas={[0.45, 0.65]} color="#5D7356" posicion={[0, 1.05, 0]} />
        <Pieza forma="cono" medidas={[0.3, 0.5]} color="#5D7356" posicion={[0, 1.4, 0]} />
        <Pieza forma="esfera" medidas={[0.07]} color={mostaza} posicion={[0, 1.7, 0]} />
        {[[0.3, 0.6, 0.35], [-0.25, 0.9, 0.3], [0.15, 1.2, 0.25], [-0.1, 0.5, 0.48]].map((b, i) => (
          <Pieza key={i} forma="esfera" medidas={[0.045]} color={FOCOS[i % 3]} posicion={b as V3} />
        ))}
      </group>
      {/* Estante con cajas */}
      <group position={[1.55, 0, -2.5]}>
        {[0.5, 1.0, 1.5].map((y, i) => (
          <Pieza key={i} forma="caja" medidas={[0.9, 0.04, 0.3]} color={crema} posicion={[0, y, 0]} />
        ))}
        <Pieza forma="caja" medidas={[0.04, 1.6, 0.3]} color={crema} posicion={[-0.45, 0.8, 0]} />
        <Pieza forma="caja" medidas={[0.04, 1.6, 0.3]} color={crema} posicion={[0.45, 0.8, 0]} />
        <Pieza forma="caja" medidas={[0.3, 0.22, 0.22]} color="#B08A62" posicion={[-0.2, 0.63, 0]} />
        <Pieza forma="caja" medidas={[0.22, 0.3, 0.2]} color="#C2BBAF" posicion={[0.2, 1.17, 0]} />
      </group>
      {/* Cartelito de oferta oscuro con luz cálida (sin texto) */}
      <group position={[0.6, 1.45, -2.9]}>
        <Pieza forma="caja" medidas={[0.7, 0.36, 0.04]} color="#2A2A2E" />
        {[-0.24, -0.08, 0.08, 0.24].map((x, i) => (
          <Pieza key={i} forma="esfera" medidas={[0.025]} color={mostaza} posicion={[x, 0.12 * (i % 2 ? 1 : -1), 0.03]}
            brillo={mostaza} contorno={false} escala={0.8 + 0.2 * Math.sin(frame / 8 + i)} />
        ))}
      </group>
      {/* Caja de cartón abierta */}
      <group position={[-1.25, 0, -1.1]} rotation={[0, 0.4, 0]}>
        <Pieza forma="caja" medidas={[0.5, 0.35, 0.4]} color="#A97E55" posicion={[0, 0.175, 0]} />
        <Pieza forma="caja" medidas={[0.5, 0.02, 0.22]} color="#B88C60" posicion={[0, 0.4, -0.27]} rotacion={[-0.9, 0, 0]} />
      </group>

      {/* ---------- MEDIO: mesa y las dos cajas ---------- */}
      <Pieza forma="caja" medidas={[1.8, 0.06, 0.8]} color={madera} posicion={[0, mesaY, 0]} />
      {[[-0.82, -0.32], [0.82, -0.32], [-0.82, 0.32], [0.82, 0.32]].map(([x, z], i) => (
        <Pieza key={i} forma="caja" medidas={[0.06, mesaY - 0.03, 0.06]} color={maderaOsc} posicion={[x, (mesaY - 0.03) / 2, z]} />
      ))}

      {/* Caja grande con cuerda flexible llena de nudos */}
      <group position={[-0.43, grandeY, 0]} rotation={[0, 0.12, giroGrande]}>
        <CajaAcrilico tam={[0.8, altoG, 0.6]} />
        {nudos.map((n, i) => (
          <Pieza key={i} forma="toro" medidas={[0.12, 0.016]} color={VERDE_CABLE} posicion={n.p}
            rotacion={[n.r[0] + flotar(frame + i * 9, 0.25, 40), n.r[1] + frame * 0.03 * (i % 2 ? 1 : -1), n.r[2]]}
            escala={latidoNudos}>
            {[0, 2.1, 4.2].map((a, k) => (
              <Pieza key={k} forma="capsula" medidas={[0.022, 0.03]} color={FOCOS[(i + k) % 3]}
                posicion={[Math.cos(a) * 0.12, Math.sin(a) * 0.12, 0]} rotacion={[0, 0, a - Math.PI / 2]} />
            ))}
          </Pieza>
        ))}
        {/* Tramo que sale hacia la punta */}
        <Linea desde={[0.06, 0.18, 0.08]} hasta={[0.22, 0.4, 0.12]} grosor={0.016} color={VERDE_CABLE} />
        {/* Punta con enchufe blanco: la "serpiente curiosa" */}
        <group position={[0.24, 0.45 + flotar(frame, 0.02, 30), 0.13]} rotation={[0, 0, -0.3 + flotar(frame, 0.15, 50)]}>
          <Pieza forma="caja" medidas={[0.1, 0.12, 0.07]} color="#F2EFE8" />
          <Pieza forma="caja" medidas={[0.012, 0.05, 0.02]} color="#9A9AA0" posicion={[-0.025, 0.08, 0]} metal={0.8} />
          <Pieza forma="caja" medidas={[0.012, 0.05, 0.02]} color="#9A9AA0" posicion={[0.025, 0.08, 0]} metal={0.8} />
          <Ojos posicion={[0, 0, 0.04]} tam={0.028} separacion={0.05} mirar={[mirarX, mirarY]} frame={frame} />
        </group>
      </group>
      {/* Aro rojo bajo la caja enredada cuando "se anudaba" */}
      <Aro posicion={[-0.43, mesaY + 0.035, 0]} radio={0.5} color={rojo} grosor={0.012}
        progreso={aparecer(frame, tAnuda, 12) * (1 - aparecer(frame, tMenos + 6, 8))} />

      {/* Caja chica con cuerda rígida casi recta */}
      <group position={[0.5, chicaY, 0.02]} rotation={[0, -0.12, giroChica]} scale={0.94 + 0.06 * saltoC}>
        <CajaAcrilico tam={[0.45, altoC, 0.4]} />
        <group position={[0, -0.12, 0]} rotation={[0, 0.25, 0.06]} scale={[1, pulsoCuerda, pulsoCuerda]}>
          <Pieza forma="cilindro" medidas={[0.02, 0.02, 0.38]} color={resalteRigida > 0.5 ? azul : VERDE_CABLE} rotacion={[0, 0, Math.PI / 2]} />
          {[-0.12, 0, 0.12].map((x, i) => (
            <Pieza key={i} forma="capsula" medidas={[0.022, 0.03]} color={FOCOS[i]} posicion={[x, 0.045, 0]} />
          ))}
          <Pieza forma="caja" medidas={[0.05, 0.06, 0.05]} color="#F2EFE8" posicion={[0.21, 0, 0]} />
        </group>
        {/* Regla azul: la cuerda sigue recta */}
        <Linea desde={[-0.2, -0.02, 0.05]} hasta={[0.2, -0.02, 0.05]} grosor={0.008} color={azul} discontinua
          progreso={mover(frame, [tRigida, tRigida + 12], [0, 1])} />
      </group>
      <Palomita posicion={[0.5, mesaY + 0.6, 0.15]} escala={palomita} />

      {/* ---------- TEXTOS ---------- */}
      <Etiqueta texto="caja chica" punto={[0.7, mesaY + 0.4, 0.2]} desplazamiento={[0.2, 0.5, 0.1]} escala={eCajaChica} />
      <Etiqueta texto="rígida" punto={[0.62, mesaY + 0.12, 0.25]} desplazamiento={[0.35, 0.3, 0.2]} escala={eRigida} color={'#FFFFFF'} />
      <Etiqueta texto="menos nudos" punto={[0.5, mesaY + 0.72, 0.15]} desplazamiento={[0.05, 0.42, 0]} escala={eMenos} />

      {/* ---------- DELANTE ---------- */}
      {/* Rollo de cinta amarilla y cartón gris sobre la mesa */}
      <Pieza forma="toro" medidas={[0.07, 0.03]} color={mostaza} posicion={[0.8, mesaY + 0.06, 0.3]} rotacion={[-Math.PI / 2, 0, 0]} />
      <Pieza forma="caja" medidas={[0.3, 0.015, 0.2]} color="#9B978F" posicion={[-0.72, mesaY + 0.04, 0.32]} rotacion={[0, 0.3, 0]} />
      <Pieza forma="cilindro" medidas={[0.1, 0.09, 0.2]} color={crema} posicion={[1.0, 0.1, 1.1]} />
    </group>
  );
}

escenas.Escena4:
import React from 'react';
import * as THREE from 'three';
import {interpolate, Easing} from 'remotion';
import {EscenaProps, Pieza, Etiqueta, Flecha, Ojos, Mat, aparecer, rebote, flotar, mover, momento} from '../lib3d';

const V = (x: number, y: number, z: number) => new THREE.Vector3(x, y, z);

// Trayectoria de la punta (cámara lenta): delante del lazo -> centro del lazo -> detrás.
const RUTA = new THREE.CatmullRomCurve3([
  V(0.62, 0.22, 0.5),
  V(0.55, 0.6, 0.55),
  V(0.14, 0.64, 0.26),
  V(0, 0.62, 0),
  V(-0.16, 0.58, -0.4),
  V(-0.36, 0.5, -0.6),
]);

const CLAMP = {extrapolateLeft: 'clamp' as const, extrapolateRight: 'clamp' as const};

export const Escena5: React.FC<EscenaProps> = ({frame, fps, palabras, paleta}) => {
  const [rojo, crema, azul, mostaza] = paleta.acentos;
  const verde = '#4F7A4A';
  const verdeOscuro = '#3B5C38';
  const focos = ['#A8574A', '#C9A54E', '#4E6E9A'];
  const madera = '#A88760';
  const carton = '#A9845C';

  // Golpes con la voz
  const tTramos = momento(palabras, fps, 'tramos', 19);
  const tAtrav = momento(palabras, fps, 'atravesarse', 49);
  const tSi = momento(palabras, fps, 'sí', 72);
  const tAsi = momento(palabras, fps, 'así', 93);
  const tPunta = momento(palabras, fps, 'punta', 115);
  const tColarse = momento(palabras, fps, 'colarse', 134);
  const tVueltas = momento(palabras, fps, 'vueltas', 165);
  const tNudo = momento(palabras, fps, 'nudo', 199);

  // Avance de la punta (cámara lenta) y apretón final
  const u0 = interpolate(frame, [tPunta + 6, tVueltas + 14], [0.2, 0.8], {...CLAMP, easing: Easing.inOut(Easing.cubic)});
  const aprieta = interpolate(frame, [tNudo - 4, tNudo + 20], [0, 1], {...CLAMP, easing: Easing.out(Easing.cubic)});
  const u = u0 + 0.15 * aprieta;
  const R = 0.4 - 0.23 * aprieta;
  const empuje = aparecer(frame, tAtrav, 4) * (1 - aparecer(frame, tSi + 8, 6));
  const sacude = Math.sin(frame * 1.3) * 0.018 * empuje;
  const C = V(sacude, 0.62, 0);

  // Puntos del cable: tramo tendido -> lazo -> salida -> recorrido de la punta
  const puntos: THREE.Vector3[] = [V(-1.05, 0.085, 0.35), V(-0.7, 0.09, 0.3), V(-0.36, Math.max(0.1, C.y - R - 0.02), 0.12)];
  const N = 14;
  for (let k = 0; k <= N; k++) {
    const th = -Math.PI / 2 - 0.35 + ((Math.PI * 2 + 0.7) * k) / N;
    puntos.push(V(C.x + R * Math.cos(th), C.y + R * Math.sin(th), 0.05 - (0.1 * k) / N));
  }
  puntos.push(V(0.38, Math.max(0.1, C.y - R - 0.04), -0.05), V(0.6, 0.1, 0.2));
  for (let s = 0; s < u - 0.04; s += 0.1) puntos.push(RUTA.getPoint(s));
  const balanceo = (1 - aparecer(frame, tPunta + 6, 10)) * flotar(frame, 0.03, 50);
  const punta = RUTA.getPoint(Math.min(1, u)).add(V(0, balanceo, 0));
  puntos.push(punta);
  const curva = new THREE.CatmullRomCurve3(puntos, false, 'centripetal');

  // Focos repartidos por el cable
  const listaFocos: React.ReactNode[] = [];
  for (let i = 0; i < 16; i++) {
    const s = 0.04 + i * 0.056;
    if (s > 0.9) break;
    const p = curva.getPointAt(s);
    const t = curva.getTangentAt(s);
    const n = V(0, 0, 1).cross(t);
    if (n.length() < 0.2) n.set(0, 1, 0);
    n.normalize();
    const enLazo = p.distanceTo(C) < R + 0.12 && p.y > 0.15;
    if (enLazo) {
      if (n.dot(p.clone().sub(C)) < 0) n.negate();
    } else if (n.y < 0) n.negate();
    const q = new THREE.Quaternion().setFromUnitVectors(V(0, 1, 0), n);
    listaFocos.push(
      <group key={i} position={p} quaternion={q}>
        <Pieza forma="cilindro" medidas={[0.022, 0.024, 0.045]} color={verdeOscuro} posicion={[0, 0.035, 0]} />
        <Pieza forma="capsula" medidas={[0.022, 0.04]} color={focos[i % 3]} posicion={[0, 0.085, 0]} />
      </group>,
    );
  }

  // Enchufe = cabeza de la "serpiente"
  const tan = curva.getTangentAt(1);
  const qEnchufe = new THREE.Quaternion().setFromUnitVectors(V(0, 0, 1), tan);
  const pop = 0.7 + 0.3 * rebote(frame, fps, 1);
  const miraX = mover(frame, [tAsi, tAsi + 8], [0.8, 0]) + mover(frame, [tNudo, tNudo + 8], [0, -0.5]);

  // Visibilidad de textos y marcas
  const visTramos = aparecer(frame, tTramos, 8) * (1 - aparecer(frame, tAsi, 6));
  const visX = aparecer(frame, tAtrav, 6) * (1 - aparecer(frame, tAsi + 4, 6));
  const visPunta = aparecer(frame, tPunta, 8) * (1 - aparecer(frame, tNudo - 2, 6));
  const visNudo = aparecer(frame, tNudo + 4, 8);
  const flecha = mover(frame, [tPunta + 2, tPunta + 18], [0, 1]) * (1 - aparecer(frame, tNudo, 6));
  const aro = mover(frame, [tVueltas, tVueltas + 14], [0, 1]) * (1 - aparecer(frame, tNudo, 6));
  const tiron = mover(frame, [tNudo, tNudo + 12], [0, 1]);

  return (
    <group>
      {/* ---------- Fondo: sala de diciembre ---------- */}
      <group position={[-1.6, 0, -2.3]}>
        <Pieza forma="cilindro" medidas={[0.07, 0.08, 0.35]} color="#7A5A3C" posicion={[0, 0.17, 0]} />
        <Pieza forma="cono" medidas={[0.5, 0.7]} color="#5E7D5A" posicion={[0, 0.65, 0]} />
        <Pieza forma="cono" medidas={[0.4, 0.6]} color="#5E7D5A" posicion={[0, 1.0, 0]} />
        <Pieza forma="cono" medidas={[0.28, 0.5]} color="#5E7D5A" posicion={[0, 1.32, 0]} />
        <Pieza forma="esfera" medidas={[0.06]} color={mostaza} posicion={[0, 1.62 + flotar(frame, 0.01, 40), 0]} />
        <Pieza forma="esfera" medidas={[0.04]} color="#A8574A" posicion={[0.22, 0.8, 0.25]} />
        <Pieza forma="esfera" medidas={[0.04]} color="#4E6E9A" posicion={[-0.18, 1.1, 0.2]} />
      </group>
      <group position={[1.7, 0, -2.2]}>
        <Pieza forma="caja" medidas={[0.04, 1.3, 0.35]} color={madera} posicion={[-0.45, 0.65, 0]} />
        <Pieza forma="caja" medidas={[0.04, 1.3, 0.35]} color={madera} posicion={[0.45, 0.65, 0]} />
        <Pieza forma="caja" medidas={[0.94, 0.03, 0.35]} color={madera} posicion={[0, 0.5, 0]} />
        <Pieza forma="caja" medidas={[0.94, 0.03, 0.35]} color={madera} posicion={[0, 1.0, 0]} />
        <Pieza forma="caja" medidas={[0.3, 0.2, 0.25]} color={carton} posicion={[-0.2, 0.62, 0]} />
        <Pieza forma="caja" medidas={[0.38, 0.22, 0.03]} color="#2A2A2E" posicion={[0.15, 1.13, 0.05]} />
        <Pieza forma="caja" medidas={[0.3, 0.04, 0.01]} color={mostaza} brillo="#4A3410" posicion={[0.15, 1.13, 0.07]} contorno={false} />
      </group>
      {/* Caja de cartón abierta */}
      <group position={[1.3, 0, -1.25]} rotation={[0, -0.4, 0]}>
        <Pieza forma="caja" medidas={[0.6, 0.4, 0.5]} color={carton} posicion={[0, 0.2, 0]} />
        <Pieza forma="caja" medidas={[0.6, 0.02, 0.24]} color="#B8936A" posicion={[0, 0.46, -0.33]} rotacion={[0.9, 0, 0]} />
        <Pieza forma="caja" medidas={[0.6, 0.02, 0.24]} color="#B8936A" posicion={[0, 0.46, 0.33]} rotacion={[-0.9, 0, 0]} />
      </group>

      {/* ---------- Medio: base y caja de acrílico en corte ---------- */}
      <Pieza forma="caja" medidas={[1.9, 0.06, 1.2]} color={madera} posicion={[0, 0.03, 0]} />
      <Pieza forma="caja" medidas={[1.8, 1.0, 0.02]} color="#DCE3E6" opacidad={0.22} contorno={false} posicion={[0, 0.56, -0.62]} />
      <Pieza forma="caja" medidas={[0.02, 1.0, 1.2]} color="#DCE3E6" opacidad={0.22} contorno={false} posicion={[-0.92, 0.56, 0]} />
      <Pieza forma="caja" medidas={[1.82, 0.025, 0.025]} color={crema} posicion={[0, 1.06, -0.62]} />
      <Pieza forma="caja" medidas={[0.025, 0.025, 1.2]} color={crema} posicion={[-0.92, 1.06, 0]} />
      <Pieza forma="caja" medidas={[0.025, 1.0, 0.025]} color={crema} posicion={[-0.92, 0.56, -0.62]} />

      {/* El cable con contorno de dibujo */}
      <mesh castShadow>
        <tubeGeometry args={[curva, 240, 0.024, 8, false]} />
        <Mat color={verde} />
      </mesh>
      <mesh>
        <tubeGeometry args={[curva, 240, 0.031, 8, false]} />
        <meshBasicMaterial color="#1B1B1F" side={THREE.BackSide} />
      </mesh>
      {listaFocos}

      {/* Enchufe blanco con ojos */}
      <group position={punta} quaternion={qEnchufe} scale={pop}>
        <Pieza forma="caja" medidas={[0.1, 0.085, 0.16]} color="#ECE8DF" posicion={[0, 0, -0.06]} />
        <Pieza forma="cilindro" medidas={[0.032, 0.026, 0.06]} color="#ECE8DF" posicion={[0, 0, -0.16]} rotacion={[Math.PI / 2, 0, 0]} />
        {[-1, 1].map((l) => (
          <Pieza key={l} forma="caja" medidas={[0.012, 0.035, 0.07]} color="#A9A9A9" metal={0.6} posicion={[0.025 * l, 0, 0.05]} />
        ))}
        <Ojos posicion={[0, 0.046, -0.07]} rotacion={[-Math.PI / 2, 0, 0]} tam={0.03} separacion={0.05} mirar={[miraX, -0.6]} frame={frame} />
      </group>

      {/* Los tramos no se atraviesan: cruce bloqueado */}
      <group position={[C.x, C.y - R, 0.12]}>
        <Pieza forma="caja" medidas={[0.16, 0.03, 0.03]} color={rojo} rotacion={[0, 0, Math.PI / 4]} escala={visX} />
        <Pieza forma="caja" medidas={[0.16, 0.03, 0.03]} color={rojo} rotacion={[0, 0, -Math.PI / 4]} escala={visX} />
      </group>

      {/* Trayectoria de la punta por dentro del lazo */}
      <Flecha desde={[0.42, 0.8, 0.45]} hasta={[-0.22, 0.72, -0.5]} color={azul} grosor={0.018} progreso={flecha} />
      {aro > 0.001 ? (
        <mesh position={C}>
          <torusGeometry args={[R + 0.07, 0.008, 8, 64, Math.PI * 2 * aro]} />
          <meshBasicMaterial color={azul} toneMapped={false} />
        </mesh>
      ) : null}
      {/* Tirón que aprieta el nudo */}
      <Flecha desde={[punta.x - 0.05, punta.y + 0.12, punta.z - 0.05]} hasta={[punta.x - 0.3, punta.y + 0.08, punta.z - 0.2]} color={azul} grosor={0.016} progreso={tiron} />

      {/* Etiquetas (máx. 2 a la vez) */}
      <Etiqueta texto="tramos" punto={[C.x - R, C.y, 0.04]} desplazamiento={[-0.42, 0.42, 0.1]} escala={visTramos} />
      <Etiqueta texto="punta" punto={[punta.x, punta.y + 0.05, punta.z]} desplazamiento={[0.2, 0.42, -0.2]} escala={visPunta} />
      <Etiqueta texto="pasa y aprieta" punto={[C.x, C.y + R, 0]} desplazamiento={[0.4, 0.45, 0]} escala={visNudo} />

      {/* ---------- Delante: cinta y cartón para enrollar ---------- */}
      <Pieza forma="toro" medidas={[0.07, 0.03]} color={mostaza} posicion={[0.9, 0.03, 0.85]} rotacion={[Math.PI / 2, 0, 0]} />
      <Pieza forma="caja" medidas={[0.45, 0.02, 0.3]} color="#9C9A94" posicion={[-0.8, 0.01, 0.85]} rotacion={[0, 0.3, 0]} />
    </group>
  );
};
